class ThermometerWidget(QWidget):
    """Animated glass thermometer with a colour-coded column and min / max markers."""

    def __init__(self):
        super().__init__()
        self.target = None
        self.shown = 20.0
        self.has = False
        self.vmin = self.vmax = None
        self.setFixedSize(124, 280)
        animate(self)

    def set_value(self, v, vmin=None, vmax=None):
        if (v, vmin, vmax) != (self.target, self.vmin, self.vmax):
            self.target, self.vmin, self.vmax = v, vmin, vmax
            self.update()

    def anim_step(self, dt, phase):
        if self.target is None:
            if self.has:
                self.has = False
                self.update()
            return
        if not self.has:
            self.shown, self.has = self.target, True
        n = approach(self.shown, self.target, dt, 8)
        if abs(n - self.target) < 0.003:
            n = self.target
        if n != self.shown:
            self.shown = n
            self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        vals = [self.shown] if self.has else []
        vals += [x for x in (self.vmin, self.vmax) if x is not None]
        lo, hi = 0.0, 40.0
        if vals:
            lo = min(0.0, math.floor((min(vals) - 5) / 10.0) * 10.0)
            hi = max(40.0, math.ceil((max(vals) + 5) / 10.0) * 10.0)
        tw, br = 22.0, 24.0
        cx, top = 50.0, 14.0
        bcy = h - br - 8
        base = bcy - br * 0.35

        def ypx(v):
            return base - (v - lo) / (hi - lo) * (base - top - 8)

        glass = QPainterPath()
        glass.setFillRule(Qt.FillRule.WindingFill)
        glass.addRoundedRect(QRectF(cx - tw / 2, top, tw, bcy - top), tw / 2, tw / 2)
        glass.addEllipse(QPointF(cx, bcy), br, br)
        p.setPen(QPen(QColor("#2b3a4d"), 2))
        p.setBrush(QColor("#0b1119"))
        p.drawPath(glass)

        p.setFont(mono_font(10))
        for v in range(int(lo), int(hi) + 1, 5):
            y = ypx(v)
            major = v % 10 == 0
            p.setPen(QPen(QColor("#6a809c") if major else QColor("#3d4b5e"), 1))
            p.drawLine(QPointF(cx + tw / 2 + 4, y), QPointF(cx + tw / 2 + (13 if major else 8), y))
            if major:
                p.setPen(QColor("#8aa0b6"))
                p.drawText(QRectF(cx + tw / 2 + 16, y - 8, 44, 16),
                           Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, f"{v}°")

        if self.has:
            col = temp_color(self.shown)
            y = ypx(self.shown)
            inner = QPainterPath()
            inner.setFillRule(Qt.FillRule.WindingFill)
            inner.addRoundedRect(QRectF(cx - tw / 2 + 3, top + 3, tw - 6, bcy - top), (tw - 6) / 2, (tw - 6) / 2)
            inner.addEllipse(QPointF(cx, bcy), br - 3, br - 3)
            p.save()
            p.setClipPath(inner)
            g = QLinearGradient(0, y, 0, h)
            g.setColorAt(0, col.lighter(125))
            g.setColorAt(1, col.darker(125))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawRect(QRectF(cx - tw / 2, y, tw, h))
            p.restore()
            gc = QColor(col)
            gc.setAlpha(55)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(gc)
            p.drawEllipse(QPointF(cx, y), 10, 10)
            p.setBrush(QColor(255, 255, 255, 38))
            p.drawRoundedRect(QRectF(cx - tw / 2 + 5, top + 8, 3, max(4.0, bcy - top - 10)), 1.5, 1.5)
            p.setBrush(col)                                     # pointer on the left
            p.drawPolygon(QPolygonF([QPointF(cx - tw / 2 - 3, y), QPointF(cx - tw / 2 - 13, y - 5),
                                     QPointF(cx - tw / 2 - 13, y + 5)]))
        for val, c in ((self.vmin, "#60a5fa"), (self.vmax, "#f87171")):      # min / max marks
            if val is None:
                continue
            y = ypx(val)
            p.setPen(QPen(QColor(c), 2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(cx - tw / 2 - 2, y), QPointF(cx + tw / 2 + 2, y))


# ---------------------------- IMU widgets -----------------------------------
class AttitudeWidget(QWidget):
    """Artificial horizon (eased)."""

    def __init__(self):
        super().__init__()
        self.troll = self.tpitch = self.roll = self.pitch = 0.0
        self.setFixedHeight(196)
        self.setMinimumWidth(180)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        animate(self)

    def set_attitude(self, roll, pitch):
        self.troll, self.tpitch = roll, pitch

    def anim_step(self, dt, phase):
        nr, np_ = approach(self.roll, self.troll, dt, 14), approach(self.pitch, self.tpitch, dt, 14)
        if abs(nr - self.roll) > 0.01 or abs(np_ - self.pitch) > 0.01:
            self.roll, self.pitch = nr, np_
            self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        side = min(w, h - 36)
        R = side / 2 - 6
        c = QPointF(w / 2, R + 6)
        clip = QPainterPath()
        clip.addEllipse(c, R, R)
        p.save()
        p.setClipPath(clip)
        p.translate(c)
        p.rotate(-self.roll)
        k = R / 45.0
        p.translate(0, self.pitch * k)
        big = R * 4
        sky = QLinearGradient(0, -R * 2, 0, 0)
        sky.setColorAt(0, QColor("#12395c"))
        sky.setColorAt(1, QColor("#2b78b4"))
        gnd = QLinearGradient(0, 0, 0, R * 2)
        gnd.setColorAt(0, QColor("#7a5230"))
        gnd.setColorAt(1, QColor("#3f2915"))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(sky)
        p.drawRect(QRectF(-big, -big, 2 * big, big))
        p.setBrush(gnd)
        p.drawRect(QRectF(-big, 0, 2 * big, big))
        p.setPen(QPen(QColor("#f2f6fa"), 2))
        p.drawLine(QPointF(-big, 0), QPointF(big, 0))
        f = QFont(self.font())
        f.setPixelSize(10)
        p.setFont(f)
        for deg in range(-40, 41, 10):
            if deg == 0:
                continue
            y = -deg * k
            half = R * (0.30 if deg % 20 == 0 else 0.18)
            p.setPen(QPen(QColor(230, 237, 245, 190), 1.5))
            p.drawLine(QPointF(-half, y), QPointF(half, y))
            if deg % 20 == 0:
                p.setPen(QColor(230, 237, 245, 190))
                p.drawText(QPointF(half + 4, y + 4), str(abs(deg)))
        p.restore()
        # roll pointer on bezel
        p.save()
        p.translate(c)
        p.rotate(-self.roll)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#fbbf24"))
        p.drawPolygon(QPolygonF([QPointF(0, -R + 3), QPointF(-5, -R + 12), QPointF(5, -R + 12)]))
        p.restore()
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor("#2b3a4d"), 3))
        p.drawEllipse(c, R, R)
        p.setPen(QPen(QColor("#fbbf24"), 3, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawLine(QPointF(c.x() - R * 0.55, c.y()), QPointF(c.x() - R * 0.18, c.y()))
        p.drawLine(QPointF(c.x() + R * 0.18, c.y()), QPointF(c.x() + R * 0.55, c.y()))
        p.drawEllipse(c, 3, 3)
        f = QFont(self.font())
        f.setBold(True)
        f.setPixelSize(11)
        p.setFont(f)
        p.setPen(QColor("#9fb0c3"))
        p.drawText(QRectF(0, side + 2, w, 16), Qt.AlignmentFlag.AlignCenter, "ATTITUDE")
        p.setFont(mono_font(10))
        p.setPen(QColor("#66788f"))
        p.drawText(QRectF(0, side + 18, w, 16), Qt.AlignmentFlag.AlignCenter,
                   f"roll {self.troll:+.1f}°  pitch {self.tpitch:+.1f}°")


class CompassWidget(QWidget):
    """Heading dial driven by the integrated gyro yaw."""

    def __init__(self):
        super().__init__()
        self.tyaw = self.yaw = 0.0
        self.setFixedHeight(196)
        self.setMinimumWidth(180)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        animate(self)

    def set_yaw(self, yaw):
        self.tyaw = yaw

    def anim_step(self, dt, phase):
        diff = ((self.tyaw - self.yaw + 180.0) % 360.0) - 180.0
        if abs(diff) > 0.01:
            self.yaw += diff * (1.0 - math.exp(-14 * dt))
            self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        side = min(w, h - 36)
        R = side / 2 - 6
        c = QPointF(w / 2, R + 6)
        rg = QRadialGradient(c, R)
        rg.setColorAt(0, QColor("#111b27"))
        rg.setColorAt(1, QColor("#0a1017"))
        p.setPen(QPen(QColor("#2b3a4d"), 3))
        p.setBrush(rg)
        p.drawEllipse(c, R, R)
        p.save()
        p.translate(c)
        p.rotate(-self.yaw)
        f = QFont(self.font())
        f.setBold(True)
        f.setPixelSize(12)
        p.setFont(f)
        for deg in range(0, 360, 10):
            p.save()
            p.rotate(deg)
            major = deg % 90 == 0
            p.setPen(QPen(QColor("#9fb0c3") if major else QColor("#3d4b5e"), 2 if major else 1))
            p.drawLine(QPointF(0, -R + 2), QPointF(0, -R + (14 if major else 7)))
            if major:
                p.setPen(QColor("#f87171") if deg == 0 else QColor("#9fb0c3"))
                p.drawText(QRectF(-12, -R + 16, 24, 16), Qt.AlignmentFlag.AlignCenter, "NESW"[deg // 90])
            p.restore()
        p.restore()
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#fbbf24"))
        p.drawPolygon(QPolygonF([QPointF(c.x(), c.y() - R * 0.55), QPointF(c.x() - 9, c.y() + R * 0.25),
                                 QPointF(c.x(), c.y() + R * 0.12), QPointF(c.x() + 9, c.y() + R * 0.25)]))
        f = QFont(self.font())
        f.setBold(True)
        f.setPixelSize(11)
        p.setFont(f)
        p.setPen(QColor("#9fb0c3"))
        p.drawText(QRectF(0, side + 2, w, 16), Qt.AlignmentFlag.AlignCenter, "HEADING (gyro)")
        p.setFont(mono_font(10))
        p.setPen(QColor("#66788f"))
        p.drawText(QRectF(0, side + 18, w, 16), Qt.AlignmentFlag.AlignCenter, f"yaw {self.tyaw:+.1f}°")


class PlotWidget(QWidget):
    """Scrolling multi-series line plot. The right edge is 'now', so stale data visibly scrolls away."""

    def __init__(self, title, unit, names, clock, min_span=1.0, history=PLOT_HISTORY_S,
                 decimals=None, colors=None, fill=False):
        super().__init__()
        self.title, self.unit, self.names, self.min_span = title, unit, names, min_span
        self.clock = clock
        self.history = history
        self.decimals = decimals
        self.colors = tuple(colors) if colors else SERIES_COLORS
        self.fill = fill
        self.hlines = []            # [(value, QColor, label)] dashed reference lines
        self.frozen = None
        self.t = deque()
        self.data = [deque() for _ in names]
        self.window = 30.0
        self.setMinimumHeight(104)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        animate(self)

    def anim_step(self, dt, phase):
        if self.frozen is None:
            self.update()

    def set_paused(self, on):
        self.frozen = self.clock() if on else None
        self.update()

    def add(self, t, values):
        self.t.append(t)
        for d, v in zip(self.data, values):
            d.append(v)
        while self.t and self.t[0] < t - self.history:
            self.t.popleft()
            for d in self.data:
                d.popleft()

    def clear(self):
        self.t.clear()
        for d in self.data:
            d.clear()
        self.update()

    def set_window(self, seconds):
        self.window = float(seconds)
        self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        L, Rm, T, B = 56, 14, 28, 22
        plot = QRectF(L, T, max(10, w - L - Rm), max(10, h - T - B))
        bg = QLinearGradient(0, 0, 0, h)
        bg.setColorAt(0, QColor("#0d141d"))
        bg.setColorAt(1, QColor("#0a1017"))
        p.setPen(QPen(QColor("#1f2b3a"), 1))
        p.setBrush(bg)
        p.drawRoundedRect(QRectF(0.5, 0.5, w - 1, h - 1), 10, 10)

        ts = list(self.t)
        tmax = self.frozen if self.frozen is not None else self.clock()
        tmin = tmax - self.window
        i0 = bisect.bisect_left(ts, tmin) if ts else 0
        vis_ts = ts[i0:]
        vis = [list(d)[i0:] for d in self.data]
        allv = [v for series in vis for v in series]
        if allv:
            allv += [h[0] for h in self.hlines]
        if allv:
            lo, hi = min(allv), max(allv)
        else:
            lo, hi = -self.min_span / 2, self.min_span / 2
        span = hi - lo
        if span < self.min_span:
            mid = (hi + lo) / 2
            lo, hi = mid - self.min_span / 2, mid + self.min_span / 2
            span = self.min_span
        lo -= span * 0.08
        hi += span * 0.08
        step = nice_step((hi - lo) / 4)
        lo = math.floor(lo / step) * step
        hi = math.ceil(hi / step) * step
        dec = max(0, -int(math.floor(math.log10(step)))) if step < 1 else 0

        p.setFont(mono_font(10))

        def ypx(v):
            return plot.bottom() - (v - lo) / (hi - lo) * plot.height()

        n = int(round((hi - lo) / step))
        for k in range(n + 1):
            v = lo + k * step
            y = ypx(v)
            p.setPen(QPen(QColor("#2a3a4f") if abs(v) < 1e-9 else QColor("#16202c"), 1))
            p.drawLine(QPointF(plot.left(), y), QPointF(plot.right(), y))
            p.setPen(QColor("#66788f"))
            p.drawText(QRectF(0, y - 8, L - 6, 16), Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight,
                       f"{v:.{dec}f}")
        ntick = 5
        for k in range(ntick + 1):
            x = plot.left() + plot.width() * k / ntick
            p.setPen(QPen(QColor("#16202c"), 1))
            p.drawLine(QPointF(x, plot.top()), QPointF(x, plot.bottom()))
            secs = self.window * (ntick - k) / ntick
            p.setPen(QColor("#66788f"))
            p.drawText(QRectF(x - 25, plot.bottom() + 3, 50, 14), Qt.AlignmentFlag.AlignCenter,
                       "now" if k == ntick else (f"-{secs / 60:g}m" if self.window >= 120 else f"-{secs:.0f}s"))

        for hv, hc, hl in self.hlines:
            y = ypx(hv)
            p.setPen(QPen(hc, 1.3, Qt.PenStyle.DashLine))
            p.drawLine(QPointF(plot.left(), y), QPointF(plot.right(), y))
            p.setFont(mono_font(10, True))
            p.setPen(hc)
            p.drawText(QRectF(plot.left() + 4, y - 14, 120, 13),
                       Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, f"{hl} {hv:g}")

        p.save()
        p.setClipRect(plot.adjusted(-2, -4, 6, 4))
        for idx, series in enumerate(vis):
            if len(series) < 2:
                continue
            pts = [QPointF(plot.left() + (t - tmin) / self.window * plot.width(), ypx(v))
                   for t, v in zip(vis_ts, series)]
            col = self.colors[idx % len(self.colors)]
            if self.fill:
                fpoly = QPolygonF(pts + [QPointF(pts[-1].x(), plot.bottom()), QPointF(pts[0].x(), plot.bottom())])
                fg = QLinearGradient(0, plot.top(), 0, plot.bottom())
                c1, c0 = QColor(col), QColor(col)
                c1.setAlpha(80)
                c0.setAlpha(0)
                fg.setColorAt(0, c1)
                fg.setColorAt(1, c0)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(fg)
                p.drawPolygon(fpoly)
            glow = QColor(col)
            glow.setAlpha(40)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(glow, 5, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            poly = QPolygonF(pts)
            p.drawPolyline(poly)
            p.setPen(QPen(col, 1.7, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.drawPolyline(poly)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(col.lighter(130))
            p.drawEllipse(pts[-1], 2.8, 2.8)
        p.restore()

        tf = QFont(self.font())
        tf.setBold(True)
        tf.setPixelSize(11)
        p.setFont(tf)
        p.setPen(QColor("#9fb0c3"))
        p.drawText(QRectF(L, 4, 220, 18), Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                   f"{self.title}  ({self.unit})")
        lf = mono_font(11, True)
        fm = QFontMetrics(lf)
        p.setFont(lf)
        x = w - Rm
        for idx in reversed(range(len(self.names))):
            last = self.data[idx][-1] if self.data[idx] else 0.0
            dec_l = self.decimals if self.decimals is not None else (2 if self.unit == "g" else 1)
            txt = f"{self.names[idx]} {last:+.{dec_l}f}"
            tw = fm.horizontalAdvance(txt) + 22
            x -= tw
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(self.colors[idx % len(self.colors)])
            p.drawEllipse(QPointF(x + 5, 13), 4, 4)
            p.setPen(self.colors[idx % len(self.colors)].lighter(120))
            p.drawText(QRectF(x + 14, 4, tw, 18), Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, txt)


# ----------------------------------------------------------------------------
# Serial link (Qt, event driven)
# ----------------------------------------------------------------------------
class SerialLink(QObject):
    line_received = Signal(str)
    closed = Signal(str)

    def __init__(self):
        super().__init__()
        self.port = QSerialPort(self)
        self.port.readyRead.connect(self._on_ready_read)
        self.port.errorOccurred.connect(self._on_error)
        self._buf = bytearray()

    @staticmethod
    def list_ports():
        out = []
        for info in QSerialPortInfo.availablePorts():
            desc = info.description() or info.manufacturer() or ""
            out.append((info.portName(), desc))
        return sorted(out)

    def is_open(self):
        return self.port.isOpen()

    def open(self, name, baud):
        self._buf.clear()
        self.port.setPortName(name)
        self.port.setBaudRate(int(baud))
        self.port.setDataBits(QSerialPort.DataBits.Data8)
        self.port.setParity(QSerialPort.Parity.NoParity)
        self.port.setStopBits(QSerialPort.StopBits.OneStop)
        self.port.setFlowControl(QSerialPort.FlowControl.NoFlowControl)
        return self.port.open(QIODevice.OpenModeFlag.ReadWrite)

    def close(self):
        if self.port.isOpen():
            self.port.flush()
            self.port.close()

    def send(self, text):
        if not self.port.isOpen():
            return False
        # Reject unexpected backlog instead of buffering stale drive commands.
        if self.port.bytesToWrite() > 2048:
            return False
        raw = (text + "\n").encode("ascii", "strict")
        return self.port.write(raw) == len(raw)

    def error_string(self):
        return self.port.errorString()

    def _on_ready_read(self):
        self._buf.extend(bytes(self.port.readAll()))
        while b"\n" in self._buf:
            raw, _, rest = self._buf.partition(b"\n")
            self._buf = bytearray(rest)
            line = raw.decode("utf-8", "ignore").strip()
            if line:
                self.line_received.emit(line)
        if len(self._buf) > 4096:
            self._buf.clear()

    def _on_error(self, err):
        if err in (QSerialPort.SerialPortError.ResourceError, QSerialPort.SerialPortError.WriteError,
                   QSerialPort.SerialPortError.ReadError, QSerialPort.SerialPortError.DeviceNotFoundError):
            msg = self.port.errorString()
            self.close()
            self.closed.emit(msg)


# ----------------------------------------------------------------------------
# Joystick (pygame)
# ----------------------------------------------------------------------------
class JoystickManager:
    def __init__(self):
        self.ok = False
        self.error = ""
        self.joy = None
        self.name = ""
        self._last_count = -1
        self.hats = []
        self.lost = False
        self.instance_id = None
        if not HAVE_PYGAME:
            self.error = "pygame is not installed  ->  pip install pygame"
            return
        try:
            pygame.display.init()
            pygame.joystick.init()
            self.ok = True
        except Exception as ex:  # pragma: no cover
            self.error = str(ex)

    def count(self):
        try:
            return pygame.joystick.get_count() if self.ok else 0
        except Exception:
            return 0

    def changed(self):
        n = self.count()
        ch = n != self._last_count
        self._last_count = n
        return ch

    def devices(self):
        out = []
        for i in range(self.count()):
            try:
                out.append((i, pygame.joystick.Joystick(i).get_name()))
            except Exception:
                pass
        return out

    def select(self, index):
        self.joy, self.name = None, ""
        self.instance_id = None
        if not self.ok or index is None or index < 0:
            return
        try:
            self.joy = pygame.joystick.Joystick(index)
            self.name = self.joy.get_name()
            self.instance_id = self.joy.get_instance_id()
        except Exception:
            self.joy = None

    @property
    def active(self):
        return self.joy is not None

    def poll(self):
        self.lost = False
        self.hats = []
        if not self.ok:
            return [], []
        try:
            for event in pygame.event.get():
                if event.type == pygame.JOYDEVICEREMOVED and event.instance_id == self.instance_id:
                    self.lost = True
            if self.lost:
                self.joy = None
                self.name = ""
                return [], []
            if self.joy is None:
                return [], []
            if not self.joy.get_init():
                raise RuntimeError("Joystick is no longer initialized")
            self.hats = [self.joy.get_hat(i) for i in range(self.joy.get_numhats())]
            axes = [self.joy.get_axis(i) for i in range(self.joy.get_numaxes())]
            buttons = [self.joy.get_button(i) for i in range(self.joy.get_numbuttons())]
            if not all(math.isfinite(x) for x in axes):
                raise ValueError("Invalid joystick sample")
            return axes, buttons
        except Exception:
            self.lost = self.joy is not None
            self.joy = None
            self.name = ""
            return [], []


