        self.relay_btns: list[PadButton] = []
        self.relay = [False, False, False]
        self.armed = False                 # set True ONLY by Arduino SYS:STATE,ARMED
        self.ready = False                 # set True ONLY by firmware v5 HELLO
        self.firmware_state = "UNKNOWN"
        self.desired_mode = "DRIVE"  # GUI mode; hardware must confirm before ARM
        self.firmware_mode = "UNKNOWN"
