    def _slider_row(self, lo, hi, val, to_text):
        s = QSlider(Qt.Orientation.Horizontal)
        s.setRange(lo, hi)
        s.setValue(val)
        s.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        lab = QLabel(to_text(val))
        lab.setFont(mono_font(13, True))
        lab.setMinimumWidth(76)
        lab.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        s.valueChanged.connect(lambda x, l=lab, f=to_text: l.setText(f(x)))
        row = QHBoxLayout()
        row.addWidget(s, 1)
        row.addWidget(lab)
        return s, row

